struct PendingAppSpecificDisable
{
    std::wstring app;
    Shortcut source;
    std::vector<DWORD> suppressedKeys;
    bool confirmed = false;
};

std::optional<PendingAppSpecificDisable> pendingAppSpecificDisable;

void RecordPendingAppSpecificDisableKey(const std::wstring& app, const Shortcut& source, DWORD key);
void ConfirmPendingAppSpecificDisable();
bool HasPendingAppSpecificDisable() const;
void ClearPendingAppSpecificDisable();

if (activatedApp && IsAppSpecificDisabledShortcutPrefix(reMap, ii, data))
{
    state.RecordPendingAppSpecificDisableKey(*activatedApp, matchedShortcut, data->lParam->vkCode);
    return 1; // swallow prefix so the target app cannot capture it
}

if (state.HasPendingAppSpecificDisable() && CandidateAborted(ii, data, state))
{
    ReplayPendingPrefixToOS(ii, state);
    state.ClearPendingAppSpecificDisable();
    return 0;
}

if (activatedApp && isRemapToDisable && state.HasPendingAppSpecificDisable() && state.PendingAppSpecificDisableConfirmed())
{
    if (SourceShortcutReleased(ii, data, it->first))
    {
        it->second.isShortcutInvoked = false;
        it->second.modifierKeysInvoked.Reset();
        it->second.isOriginalActionKeyPressed = false;
        state.SetActivatedApp(KeyboardManagerConstants::NoActivatedApp);
        state.ClearPendingAppSpecificDisable();
    }
    return 1; // do not replay the original source keys into the target app
}

TEST_METHOD(AppSpecificShortcutToDisable_ShouldNotLeakFirstModifierBeforeExactMatch)
{
    Shortcut src;
    src.SetKey(VK_SHIFT);
    src.SetKey(0x41);
    testState.AddAppSpecificShortcut(testApp1, src, (DWORD)CommonSharedConstants::VK_DISABLED);
    mockedInputHandler.SetForegroundProcess(testApp1);

    mockedInputHandler.SendVirtualInput({ { .type = INPUT_KEYBOARD, .ki = { .wVk = VK_SHIFT } } });
    Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_SHIFT));

    mockedInputHandler.SendVirtualInput({ { .type = INPUT_KEYBOARD, .ki = { .wVk = 0x41 } } });
    Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(VK_SHIFT));
    Assert::AreEqual(false, mockedInputHandler.GetVirtualKeyState(0x41));
}
